const staticData = $getWorkflowStaticData('global');
const values = items[0].json.values || [];
if (!Array.isArray(values) || values.length < 2) return [];
const headers = (values[0] || []).map((h) => String(h || '').trim());
const seen = staticData.seenFormTs2 || {};
const out = [];
for (let i = 1; i < values.length; i++) {
  const row = values[i] || [];
  const obj = {};
  headers.forEach((h, idx) => { obj[h] = String(row[idx] || '').trim(); });
  const ts = obj.Timestamp || ('row-' + i);
  if (seen[ts]) continue;
  seen[ts] = 1;
  out.push({ json: obj });
}
staticData.seenFormTs2 = seen;
return out;

const raw = items[0].json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const nv = body.namedValues && typeof body.namedValues === 'object' ? body.namedValues : {};
function pick(obj, keys) {
  const bag = {};
  for (const [k, v] of Object.entries(obj || {})) bag[String(k).trim()] = v;
  for (const key of keys) {
    const val = bag[key] != null ? bag[key] : obj[key];
    if (Array.isArray(val) && val[0]) return String(val[0]).trim();
    if (val != null && String(val).trim()) return String(val).trim();
  }
  return '';
}
const keysName = ['fullName', 'Name', 'name', 'Full name'];
